"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["87079"],{96803(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_termina_depois_da_fase","status":422,"titulo":"A etapa termina depois da fase que a abriga"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_termina_depois_da_fase","requisitos":[],"oQueAconteceu":["O fim declarado para uma etapa \xe9 posterior ao fim da fase do cronograma em que ela\\nacontece. A etapa \xe9 parte da fase, ent\xe3o o per\xedodo dela cabe dentro do per\xedodo da fase. A\\nmensagem de detalhe cita a etapa, o fim dela e o fim da fase. A recusa sai com **422**.","S\xf3 se compara o que os dois lados declararam: fase sem per\xedodo n\xe3o cont\xe9m nada, e etapa\\nsem per\xedodo acontece no per\xedodo da fase. Fim igual ao da fase passa. A etapa que declara\\napenas um dos extremos herda o outro da fase.","A regra vale ao definir as etapas, ao definir o cronograma (que pode encurtar a fase por\\nbaixo de etapas j\xe1 datadas) e, como defesa, na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, para que nenhuma vers\xe3o congele uma prova marcada\\npara depois do fim da fase que a cont\xe9m."],"comoResolver":["Alinhe as datas: antecipe o fim da etapa\\n(`PUT /api/selecao/processos-seletivos/{id}/etapas`) ou estenda o fim da fase\\n(`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`), conforme o edital.\\nRepita ent\xe3o a opera\xe7\xe3o recusada."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);